// Matrix is a matrix of integers.
type Matrix *matrixData

type matrixData struct {
	rows [][]int
}

// New parses a string of whitespace-separated integers into a Matrix.
// The string is expected to contain rows separated by newlines, with each
// row containing space-separated integers. All rows must have the same
// number of columns. New returns an error if the input is malformed, if
// any element is not a valid integer, or if any integer overflows.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	rows := make([][]int, len(lines))
	for i, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: empty row")
		}
		row := make([]int, len(fields))
		for j, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[j] = v
		}
		rows[i] = row
	}
	// verify all rows have the same number of columns
	width := len(rows[0])
	for i, row := range rows {
		if len(row) != width {
			return nil, errors.New("matrix: uneven rows")
		}
	}
	return (*Matrix)(&matrixData{rows: rows}), nil
}
```

