package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a two-dimensional grid of integers, where each element is
// addressed by a zero-based row and column index.
type Matrix [][]int

// New parses s into a Matrix. The string is expected to contain rows of
// whitespace-separated integers, with each row on its own line. All rows
// must contain the same number of columns. New returns an error if any row
// is empty, if the rows are uneven, or if any element is not a valid integer
// (including values that overflow the integer range).
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	rows := make(Matrix, len(lines))
	for i, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: row must not be empty")
		}
		row := make([]int, len(fields))
		for j, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[j] = v
		}
		rows[i] = row
	}
	width := len(rows[0])
	for i, row := range rows {
		if len(row) != width {
			return nil, errors.New("matrix: uneven rows")
		}
	}
	return rows, nil
}

// Cols returns the columns of the matrix as a new [][]int. Each column is
// read top-to-bottom, and the columns are ordered left-to-right. The
// returned data is an independent copy and does not share storage with the
// matrix, so mutating it has no effect on the matrix.
func (m Matrix) Cols() [][]int {
	if len(m) == 0 {
		return nil
	}
	numCols := len(m[0])
	cols := make([][]int, numCols)
	for c := 0; c < numCols; c++ {
		col := make([]int, len(m))
		for r, row := range m {
			col[r] = row[c]
		}
		cols[c] = col
	}
	return cols
}

// Rows returns the rows of the matrix as a new [][]int. Each row is read
// left-to-right, and the rows are ordered top-to-bottom. The returned data
// is an independent copy and does not share storage with the matrix, so
// mutating it has no effect on the matrix.
func (m Matrix) Rows() [][]int {
	rows := make(Matrix, len(m))
	for i, row := range m {
		rows[i] = make([]int, len(row))
		copy(rows[i], row)
	}
	return rows
}

// Set sets the element at the given row and column to val. It returns true
// if the element exists (that is, row and col are within the matrix bounds)
// and false otherwise. Rows and columns are zero-based.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m) {
		return false
	}
	if col < 0 || col >= len(m[row]) {
		return false
	}
	m[row][col] = val
	return true
}

